// Approach: The last move to stair i comes from i-1 or i-2, so add their ways.
long long climbStairs(int n) {
    if (n < 0) return 0;
    long long twoBefore = 1, oneBefore = 1; // stairs 0 and 1
    for (int stair = 2; stair <= n; ++stair) {
        long long current = oneBefore + twoBefore;
        twoBefore = oneBefore;
        oneBefore = current;
    }
    return oneBefore;
}

s16-frog-jump-dp-3.code:
// Approach: The cheapest path to stone i ends with a jump from i-1 or i-2.
#include <algorithm>
#include <cstdlib>
#include <vector>
using namespace std;
int frogJump(const vector<int>& height) {
    int n = (int)height.size();
    if (n < 2) return 0;
    int twoBefore = 0, oneBefore = abs(height[1] - height[0]);
    // Only the costs for the two previous stones are needed.
    for (int i = 2; i < n; ++i) {
        int current = min(oneBefore + abs(height[i] - height[i - 1]),
                          twoBefore + abs(height[i] - height[i - 2]));
        twoBefore = oneBefore;
        oneBefore = current;
    }
    return oneBefore;
}

s16-frog-jump-with-k-distances-dp-4.code:
// Approach: For each stone, try the previous k stones as the final jump.
#include <algorithm>
#include <climits>
#include <cstdlib>
#include <vector>
using namespace std;
int frogJumpK(const vector<int>& height, int k) {
    int n = (int)height.size();
    if (n < 2) return 0;
    if (k <= 0) return -1;
    vector<int> dp(n, INT_MAX);
    dp[0] = 0;
    // Try each reachable earlier stone as the final jump into i.
    for (int i = 1; i < n; ++i)
        for (int jump = 1; jump <= k && jump <= i; ++jump)
            dp[i] = min(dp[i], dp[i - jump] +
                               abs(height[i] - height[i - jump]));
    return dp.back();
}

