    return dp[capacity];
}

s16-longest-common-subsequence-dp-25.code:
// Approach: When characters match, extend a shorter LCS; otherwise keep the better result after
//   skipping one character.
#include <algorithm>
#include <string>
#include <vector>
using namespace std;
int longestCommonSubsequence(const string& a, const string& b) {
    // A match extends the diagonal LCS; otherwise keep the better neighbor.
    vector<int> previous(b.size() + 1, 0), current(b.size() + 1, 0);
    for (char x : a) {
        fill(current.begin(), current.end(), 0);
        for (int j = 1; j <= (int)b.size(); ++j)
            current[j] = x == b[j - 1] ? 1 + previous[j - 1]
                                       : max(previous[j], current[j - 1]);
        previous.swap(current);
    }
    return previous.back();
}

s16-print-longest-common-subsequence-dp-.code:
// Approach: Build the LCS length table, then backtrack from its bottom-right corner to recover one
//   subsequence.
#include <algorithm>
#include <string>
#include <vector>
using namespace std;
string printLCS(const string& a, const string& b) {
    // LCS lengths let us backtrack an actual sequence.
    int n = (int)a.size(), m = (int)b.size();
    vector<vector<int>> dp(n + 1, vector<int>(m + 1, 0));
    for (int i = 1; i <= n; ++i)
        for (int j = 1; j <= m; ++j)
            dp[i][j] = a[i - 1] == b[j - 1] ? 1 + dp[i - 1][j - 1]
                                            : max(dp[i - 1][j], dp[i][j - 1]);
    string result;
    for (int i = n, j = m; i > 0 && j > 0;) {
        if (a[i - 1] == b[j - 1]) {
            result.push_back(a[i - 1]);
            --i; --j;
        } else if (dp[i - 1][j] >= dp[i][j - 1]) --i;
        else --j;
    }
    reverse(result.begin(), result.end());
    return result;
}

s16-longest-common-substring-dp-27.code:
// Approach: A matching suffix extends only when the current characters match; otherwise its length
//   resets to zero.
#include <algorithm>
#include <string>
#include <vector>
using namespace std;
int longestCommonSubstring(const string& a, const string& b) {
    // A mismatch resets the common suffix length to zero.
    vector<int> previous(b.size() + 1, 0), current(b.size() + 1, 0);
    int answer = 0;
    for (char x : a) {
        fill(current.begin(), current.end(), 0);
        for (int j = 1; j <= (int)b.size(); ++j)
            if (x == b[j - 1]) {
                current[j] = previous[j - 1] + 1;
                answer = max(answer, current[j]);
            }
        previous.swap(current);
    }
    return answer;
}

s16-longest-palindromic-subsequence-dp-2.code:
// Approach: The LPS is an LCS between the string and its reverse.
#include <algorithm>
#include <string>
#include <vector>
using namespace std;
int longestPalindromeSubseq(const string& s) {
    string reversed(s.rbegin(), s.rend());
    vector<int> previous(s.size() + 1, 0), current(s.size() + 1, 0);
    // Compare s with its reverse using the usual LCS recurrence.
    for (char x : s) {
        fill(current.begin(), current.end(), 0);
        for (int j = 1; j <= (int)s.size(); ++j)
            current[j] = x == reversed[j - 1] ? 1 + previous[j - 1]
                                              : max(previous[j], current[j - 1]);
        previous.swap(current);
    }
    return previous.back();
}

s16-minimum-insertions-to-make-string-pa.code:
// Approach: Keep a longest palindromic subsequence and insert a matching partner for every other
//   character.
#include <algorithm>
#include <string>
#include <vector>
using namespace std;
int minInsertionsForPalindrome(const string& s) {
    // Keep the longest palindromic subsequence; insert the rest.
    string reversed(s.rbegin(), s.rend());
    int n = (int)s.size();
    vector<int> previous(n + 1, 0), current(n + 1, 0);
    for (char x : s) {
        fill(current.begin(), current.end(), 0);
        for (int j = 1; j <= n; ++j)
            current[j] = x == reversed[j - 1] ? 1 + previous[j - 1]
                                              : max(previous[j], current[j - 1]);
        previous.swap(current);
    }
    return n - previous[n];
}

s16-minimum-insertions-deletions-to-conv.code:
// Approach: Keep a longest common subsequence; delete the other characters from the first string and
//   insert the missing characters of the second.
#include <algorithm>
#include <string>
#include <vector>
using namespace std;
int minInsertionsAndDeletions(const string& from, const string& to) {
    // Characters outside the LCS must be deleted or inserted.
    int n = (int)from.size(), m = (int)to.size();
    vector<int> previous(m + 1, 0), current(m + 1, 0);
    for (char x : from) {
        fill(current.begin(), current.end(), 0);
        for (int j = 1; j <= m; ++j)
            current[j] = x == to[j - 1] ? previous[j - 1] + 1
                                        : max(previous[j], current[j - 1]);
        previous.swap(current);
    }
    return n + m - 2 * previous[m];
}

s16-shortest-common-supersequence-dp-31.code:
// Approach: Backtrack through the LCS table, appending the unmatched character from whichever string
//   is skipped.
#include <algorithm>
#include <string>
#include <vector>
using namespace std;
string shortestCommonSupersequence(const string& a, const string& b) {
    // Follow the LCS table to combine strings without duplicating matches.
    int n = (int)a.size(), m = (int)b.size();
    vector<vector<int>> dp(n + 1, vector<int>(m + 1, 0));
    for (int i = 1; i <= n; ++i)
        for (int j = 1; j <= m; ++j)
            dp[i][j] = a[i - 1] == b[j - 1] ? dp[i - 1][j - 1] + 1
                                            : max(dp[i - 1][j], dp[i][j - 1]);
    string result;
    int i = n, j = m;
    while (i > 0 && j > 0) {
        if (a[i - 1] == b[j - 1]) {
            result.push_back(a[--i]); --j;
        } else if (dp[i - 1][j] >= dp[i][j - 1]) result.push_back(a[--i]);
        else result.push_back(b[--j]);
    }
    while (i > 0) result.push_back(a[--i]);
    while (j > 0) result.push_back(b[--j]);
    reverse(result.begin(), result.end());
    return result;
}

