// Approach: Scan the source left to right and update target-prefix counts backward. Count exactly for
//   LeetCode; use modulo 1e9+7 where the judge requires it.
#include <string>
#include <vector>
using namespace std;
long long numDistinct(const string& source, const string& target,
                      long long mod = 0) {
    vector<long long> ways(target.size() + 1, 0);
    ways[0] = 1;
    for (char ch : source)
        for (int j = (int)target.size(); j >= 1; --j)
            if (ch == target[j - 1]) {
                ways[j] += ways[j - 1];
                if (mod) ways[j] %= mod; // optional judge-specific modulo
            }
    return ways.back();
}

s16-edit-distance-dp-33.code:
// Approach: At each pair of prefixes, either match equal characters or pay one for insert, delete, or
//   replace.
#include <algorithm>
#include <numeric>
#include <string>
#include <vector>
using namespace std;
int editDistance(const string& a, const string& b) {
    // Empty-to-prefix distance is the prefix length (all insertions).
    int m = (int)b.size();
    vector<int> previous(m + 1), current(m + 1);
    iota(previous.begin(), previous.end(), 0);
    for (int i = 1; i <= (int)a.size(); ++i) {
        current[0] = i;
        for (int j = 1; j <= m; ++j)
            current[j] = a[i - 1] == b[j - 1] ? previous[j - 1]
                         : 1 + min({previous[j], current[j - 1], previous[j - 1]});
        previous.swap(current);
    }
    return previous[m];
}

s16-wildcard-matching-dp-34.code:
// Approach: A '?' consumes one character; a '*' consumes zero or more. Update pattern-prefix matches
//   for each text prefix.
#include <string>
#include <vector>
using namespace std;
bool wildcardMatch(const string& pattern, const string& text) {
    // Empty pattern matches empty text; only '*' can extend that match.
    int m = (int)text.size();
    vector<char> previous(m + 1, false), current(m + 1, false);
    previous[0] = true;
    for (char p : pattern) {
        current[0] = p == '*' && previous[0];
        for (int j = 1; j <= m; ++j)
            current[j] = p == '*' ? (previous[j] || current[j - 1])
                       : (p == '?' || p == text[j - 1]) && previous[j - 1];
        previous.swap(current);
        fill(current.begin(), current.end(), false);
    }
    return previous[m];
}

