long long maxProfitKTransactions(int k, const vector<int>& prices) {
    // With enough transactions, take every positive rise.
    int n = (int)prices.size();
    if (k <= 0 || n < 2) return 0;
    if (k >= n / 2) {
        long long profit = 0;
        for (int i = 1; i < n; ++i)
            profit += max(0, prices[i] - prices[i - 1]);
        return profit;
    }
    vector<long long> buy(k + 1, LLONG_MIN / 4), sell(k + 1, 0);
    for (int price : prices)
        for (int t = k; t >= 1; --t) {
            sell[t] = max(sell[t], buy[t] + price);
            buy[t] = max(buy[t], sell[t - 1] - price);
        }
