#include <climits>
#include <vector>
using namespace std;
long long maxProfitCooldown(const vector<int>& prices) {
    // hold, sold, and rest are the three end-of-day states.
    long long hold = LLONG_MIN / 4, sold = LLONG_MIN / 4, rest = 0;
    for (int price : prices) {
        long long nextHold = max(hold, rest - price);
        long long nextSold = hold + price;
        long long nextRest = max(rest, sold);
        hold = nextHold; sold = nextSold; rest = nextRest;
    }
    return max(rest, sold);
}

