vector<int> printLIS(const vector<int>& values) {
    // parent remembers predecessors used to rebuild the subsequence.
    int n = (int)values.size();
    if (!n) return {};
    vector<int> length(n, 1), parent(n);
    int end = 0;
    for (int i = 0; i < n; ++i) {
        parent[i] = i;
        for (int j = 0; j < i; ++j)
            if (values[j] < values[i] && length[j] + 1 > length[i]) {
                length[i] = length[j] + 1;
                parent[i] = j;
            }
        if (length[i] > length[end]) end = i;
    }
    vector<int> result;
    for (int i = end;; i = parent[i]) {
        result.push_back(values[i]);
        if (parent[i] == i) break;
    }
    reverse(result.begin(), result.end());
    return result;
}

