vector<int> largestDivisibleSubset(vector<int> values) {
    // Sorting ensures a divisible predecessor is considered first.
    if (values.empty()) return {};
    sort(values.begin(), values.end());
    int n = (int)values.size(), end = 0;
    vector<int> length(n, 1), parent(n);
    for (int i = 0; i < n; ++i) {
        parent[i] = i;
        for (int j = 0; j < i; ++j)
            if (values[j] != 0 && values[i] % values[j] == 0
                && length[j] + 1 > length[i]) {
                length[i] = length[j] + 1;
                parent[i] = j;
            }
        if (length[i] > length[end]) end = i;
    }
    vector<int> result;
    for (int i = end;; i = parent[i]) {
        result.push_back(values[i]);
        if (parent[i] == i) break;
    }
    reverse(result.begin(), result.end());
    return result;
}

