// Approach: Sort words by length. Deleting each character gives every possible immediate predecessor.
#include <algorithm>
#include <string>
#include <unordered_map>
#include <vector>
using namespace std;
int longestStringChain(vector<string> words) {
    sort(words.begin(), words.end(),
         [](const string& a, const string& b) { return a.size() < b.size(); });
    unordered_map<string, int> best;
    int answer = 0;
    // Every shorter predecessor was processed earlier after sorting by length.
    for (const string& word : words) {
        int length = 1;
        for (int i = 0; i < (int)word.size(); ++i) {
            string previous = word.substr(0, i) + word.substr(i + 1);
            auto it = best.find(previous);
            if (it != best.end()) length = max(length, it->second + 1);
        }
        best[word] = max(best[word], length);
        answer = max(answer, best[word]);
    }
    return answer;
}

