// Approach: Compute increasing lengths from the left and decreasing lengths from the right; combine
//   them at each peak.
#include <algorithm>
#include <vector>
using namespace std;
int longestBitonicSubsequence(const vector<int>& values) {
    int n = (int)values.size(), answer = 0;
    vector<int> up(n, 1), down(n, 1);
    for (int i = 0; i < n; ++i)
        for (int j = 0; j < i; ++j)
            if (values[j] < values[i]) up[i] = max(up[i], up[j] + 1);
    for (int i = n - 1; i >= 0; --i)
        for (int j = n - 1; j > i; --j)
            if (values[j] < values[i]) down[i] = max(down[i], down[j] + 1);
    for (int i = 0; i < n; ++i)
        if (up[i] > 1 && down[i] > 1)
            answer = max(answer, up[i] + down[i] - 1);
    return answer; // requires both increasing and decreasing parts
}

