    int n = (int)values.size(), longest = 0;
    vector<int> length(n, 1);
    vector<long long> count(n, 1);
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < i; ++j) if (values[j] < values[i]) {
            if (length[j] + 1 > length[i]) {
                length[i] = length[j] + 1;
                count[i] = count[j];
