// Approach: Fill interval costs from shorter matrix chains to longer ones, trying every split.
#include <algorithm>
#include <climits>
#include <vector>
using namespace std;
long long matrixChainTabulation(const vector<int>& dims) {
    int n = (int)dims.size() - 1;
    if (n <= 0) return 0;
    vector<vector<long long>> dp(n + 1, vector<long long>(n + 1, 0));
    // Solve shorter chains before longer chains that use them.
    for (int length = 2; length <= n; ++length)
        for (int i = 1; i + length - 1 <= n; ++i) {
            int j = i + length - 1;
            dp[i][j] = LLONG_MAX / 4;
            for (int split = i; split < j; ++split)
                dp[i][j] = min(dp[i][j], dp[i][split] + dp[split + 1][j]
                         + 1LL * dims[i - 1] * dims[split] * dims[j]);
        }
    return dp[1][n];
}

