// Approach: Treat each matrix row as the base of a histogram of consecutive ones. A monotonic stack
//   finds that histogram's largest rectangle.
#include <algorithm>
#include <stack>
#include <vector>
using namespace std;
int histogramArea(const vector<int>& height) {
    // A shorter bar closes rectangles limited by taller bars.
    stack<int> increasing;
    int answer = 0, n = (int)height.size();
    for (int i = 0; i <= n; ++i) {
        int current = i == n ? 0 : height[i];
        while (!increasing.empty() && height[increasing.top()] >= current) {
            int h = height[increasing.top()]; increasing.pop();
            int left = increasing.empty() ? -1 : increasing.top();
            answer = max(answer, h * (i - left - 1));
        }
        increasing.push(i);
    }
    return answer;
}
int maximalRectangle(const vector<vector<char>>& matrix) {
    if (matrix.empty() || matrix[0].empty()) return 0;
    vector<int> height(matrix[0].size(), 0);
    int answer = 0;
    for (const auto& row : matrix) {
        for (int c = 0; c < (int)row.size(); ++c)
            height[c] = row[c] == '1' ? height[c] + 1 : 0;
        answer = max(answer, histogramArea(height));
    }
    return answer;
}

s16-count-square-submatrices-with-all-on.code:
// Approach: A one-cell ends a square of side one plus the minimum square side above, left, and
//   diagonally above-left.
#include <algorithm>
#include <vector>
using namespace std;
long long countSquares(const vector<vector<int>>& matrix) {
    if (matrix.empty() || matrix[0].empty()) return 0;
    int cols = (int)matrix[0].size();
    vector<int> dp(cols + 1, 0);
    long long answer = 0;
    for (const auto& row : matrix) {
        int diagonal = 0;
        for (int c = 1; c <= cols; ++c) {
            int above = dp[c];
            dp[c] = row[c - 1] == 0 ? 0
                  : 1 + min({above, dp[c - 1], diagonal});
            answer += dp[c]; // one square for every possible side length
            diagonal = above;
        }
    }
    return answer;
}
